/* science-bank.js: Science practice-test question banks (original questions based on the unit/activity topics of Issues and Science for California, Grade 7 (SEPUP, 3rd edition, NGSS)). GENERATED by study-guide-src/build.js from science/unit-*.js. */
window.SCIENCE_BANK = {"1":{"num":1,"letter":"A","title":"Ecology","lessons":[{"id":"A1","title":"Introduced Species and Ecosystem Change","qs":[{"lesson":"A1","scen":false,"type":"mc","q":"What makes an introduced species invasive?","a":"It spreads and harms the ecosystem it was moved into","wrong":["It was moved by people","It is a plant rather than an animal","It is larger than native species"],"why":"Being moved by people makes it introduced; causing harm and spreading makes it invasive."},{"lesson":"A1","scen":false,"type":"mc","q":"Which is a native species?","a":"A species that naturally lives in an area","wrong":["A species brought in by ships","Any species that is endangered","A species that only lives in zoos"],"why":"Native means it belongs there naturally, without people moving it."},{"lesson":"A1","scen":false,"type":"tf","q":"Every introduced species becomes invasive.","a":"False","why":"Many introduced species never spread or cause harm; only some become invasive."},{"lesson":"A1","scen":false,"type":"tf","q":"An invasive species often has few natural predators in its new home.","a":"True","why":"Without predators or diseases that controlled it at home, its population can grow quickly."},{"lesson":"A1","scen":false,"type":"fill","q":"An introduced species that spreads and causes harm is called an ___ species.","alts":["invasive"],"a":"invasive","why":"Invasive species spread and damage ecosystems or economies."},{"lesson":"A1","scen":false,"type":"fill","q":"Giving up one benefit to get another when making a decision is called a ___.","alts":["trade-off","tradeoff","trade off"],"a":"trade-off","why":"Trade-offs come up in almost every environmental decision."},{"lesson":"A1","scen":false,"type":"short","q":"Give one reason an invasive species can grow so quickly in a new place.","groups":[["predator","disease","compet","reproduc","food","no enem"]],"a":"It has no natural predators or diseases there, so nothing keeps its numbers down.","why":"Invasive species escape the natural controls of their home ecosystem."},{"lesson":"A1","scen":false,"type":"mc","q":"Which human action most likely introduces aquatic species to a new lake?","a":"Moving a boat from one lake to another without cleaning it","wrong":["Planting native trees by the shore","Counting fish with a net","Measuring the water temperature"],"why":"Organisms such as mussels can cling to boats and trailers and hitch a ride."},{"lesson":"A1","scen":true,"type":"mc","q":"A large fish was added to a lake to give local people more food to sell. Years later, many kinds of small native fish have disappeared. What is the best explanation?","a":"The large fish preyed on the small native fish, reducing their populations","wrong":["The small fish moved to the ocean","The lake water got colder each year","The small fish became the large fish"],"why":"A new predator can sharply reduce prey populations that never evolved defenses against it."},{"lesson":"A1","scen":true,"type":"mc","q":"Zebra-mussel-like shellfish clog the water pipes of a power plant on a river. Which is the best way to stop them spreading to other rivers?","a":"Require boats to be cleaned and drained before moving to new water","wrong":["Add more mussels to compete with them","Stop measuring the river","Plant grass along the river"],"why":"Prevention, such as cleaning boats, stops hitchhiking organisms."},{"lesson":"A1","scen":true,"type":"tf","q":"A town decides to keep an introduced fish because it brings jobs, even though native fish declined. This decision involves a trade-off.","a":"True","why":"The town gains jobs and income but loses native biodiversity: a classic trade-off."},{"lesson":"A1","scen":true,"type":"short","q":"A pet store owner wants to release unsold goldfish into a local pond. Explain one risk to the pond ecosystem.","groups":[["compet","eat","food","invasive","native","disease"]],"a":"The goldfish could compete with native fish for food, eat their eggs or bring disease, and might become invasive.","why":"Released pets are a common source of invasive species."},{"lesson":"A1","scen":true,"type":"fill","q":"A scientist compares the number of native snails before (200) and after (50) a new species arrived. The native snail population ___ by 150.","alts":["decreased","declined","dropped","fell","went down"],"a":"decreased","why":"200 - 50 = 150, so the population decreased by 150."},{"lesson":"A1","scen":true,"type":"mc","q":"A student is preparing a presentation on whether to remove an invasive plant. Which evidence would be MOST useful?","a":"Data on native plant numbers before and after the invasive plant arrived","wrong":["Her favorite color of flower","A picture of the plant only","The price of seeds at a store"],"why":"Before-and-after data shows whether the plant is actually causing harm."}]},{"id":"A2","title":"Habitats, Transects and Abiotic Factors","qs":[{"lesson":"A2","scen":false,"type":"mc","q":"Which is an abiotic factor?","a":"Water temperature","wrong":["Algae","Fungi","Earthworms"],"why":"Abiotic means nonliving; temperature is a nonliving condition."},{"lesson":"A2","scen":false,"type":"mc","q":"Which is a biotic factor?","a":"A decomposing leaf","wrong":["Sunlight","Rocks","Air pressure"],"why":"A once-living leaf is biotic."},{"lesson":"A2","scen":false,"type":"tf","q":"Soil and sunlight are biotic factors.","a":"False","why":"They are nonliving, so they are abiotic factors."},{"lesson":"A2","scen":false,"type":"tf","q":"A transect lets ecologists estimate what lives in an area without counting every organism.","a":"True","why":"Sampling along a line gives a representative picture."},{"lesson":"A2","scen":false,"type":"fill","q":"The place that provides an organism with food, water and shelter is its ___.","alts":["habitat"],"a":"habitat","why":"A habitat meets an organism’s needs."},{"lesson":"A2","scen":false,"type":"fill","q":"A line along which scientists sample organisms at regular intervals is called a ___.","alts":["transect"],"a":"transect","why":"Transects are a standard ecology sampling tool."},{"lesson":"A2","scen":false,"type":"short","q":"Why do scientists sample an area instead of counting every organism in it?","groups":[["too many","time","impossible","large","estimat","hard"]],"a":"There are far too many organisms and too much area, so a sample lets them estimate efficiently.","why":"Sampling saves time and still represents the whole area."},{"lesson":"A2","scen":false,"type":"mc","q":"Why is it better to take samples at many points along a transect than at just one point?","a":"More samples give a more reliable picture of the whole area","wrong":["One point is always wrong","It makes the transect shorter","It changes the abiotic factors"],"why":"Larger samples reduce the chance that one unusual spot misleads you."},{"lesson":"A2","scen":true,"type":"mc","q":"Brine shrimp eggs are placed in cups with different amounts of salt. Most hatch in medium salt and almost none in fresh water or very salty water. What does this show?","a":"The shrimp have a range of salt conditions in which they survive best","wrong":["Salt is a biotic factor","Shrimp do not need water","The cups had too much light"],"why":"Each species has a tolerance range for an abiotic factor."},{"lesson":"A2","scen":true,"type":"mc","q":"Along a transect from a stream to a dry hilltop, ferns are common near the stream but absent on the hilltop. Which abiotic factor most likely explains this?","a":"Amount of water in the soil","wrong":["The number of birds","The color of the ferns","The time of day of sampling"],"why":"Ferns need moist soil; moisture decreases uphill."},{"lesson":"A2","scen":true,"type":"tf","q":"If a drought lowers a pond’s water level for months, the populations of fish and frogs in the pond may change.","a":"True","why":"Water is an abiotic factor; less of it changes what can survive."},{"lesson":"A2","scen":true,"type":"short","q":"A student counts 12 snails in a 1 m² square and wants to estimate snails in a 50 m² garden. What should she do to get a more reliable estimate?","groups":[["more","several","many","repeat"]],"a":"Sample several squares in different spots, average them, then multiply by 50.","why":"More, spread-out samples make an estimate more reliable."},{"lesson":"A2","scen":true,"type":"fill","q":"A lake warms by 4 °C over many years. Temperature is a(n) ___ factor that could change which fish can live there.","alts":["abiotic"],"a":"abiotic","why":"Temperature is a nonliving (abiotic) factor."},{"lesson":"A2","scen":true,"type":"mc","q":"A habitat has plenty of food and water but no places to hide or nest. What is it missing?","a":"Shelter","wrong":["Sunlight","Biotic factors","Abiotic factors"],"why":"Organisms need shelter as well as food and water."}]},{"id":"A3","title":"Populations and Interactions","qs":[{"lesson":"A3","scen":false,"type":"mc","q":"What is a population?","a":"All the members of one species living in an area","wrong":["All the species in an ecosystem","All the nonliving things in a habitat","One organism and its offspring only"],"why":"A population is one species in one place."},{"lesson":"A3","scen":false,"type":"mc","q":"Which relationship benefits both species?","a":"Mutualism","wrong":["Parasitism","Predation","Competition"],"why":"Mutualism is +/+."},{"lesson":"A3","scen":false,"type":"mc","q":"A tick feeding on a deer is an example of","a":"parasitism","wrong":["mutualism","commensalism","competition"],"why":"The tick benefits and the deer is harmed."},{"lesson":"A3","scen":false,"type":"tf","q":"A population can keep growing quickly forever if it starts with enough food.","a":"False","why":"Limiting factors eventually slow growth near the carrying capacity."},{"lesson":"A3","scen":false,"type":"tf","q":"Two species that eat the same seeds in the same field are in competition.","a":"True","why":"They need the same limited resource."},{"lesson":"A3","scen":false,"type":"fill","q":"The largest population an environment can support over time is its ___ ___.","alts":["carrying capacity"],"a":"carrying capacity","why":"Carrying capacity is set by limiting factors."},{"lesson":"A3","scen":false,"type":"fill","q":"A relationship where one species benefits and the other is neither helped nor harmed is called ___.","alts":["commensalism"],"a":"commensalism","why":"Commensalism is +/0."},{"lesson":"A3","scen":false,"type":"short","q":"Name two limiting factors that can stop a population from growing.","groups":[["food","water","space","shelter","predator","disease","light","nest"],["food","water","space","shelter","predator","disease","light","nest"]],"a":"Food supply and predators (also water, space, shelter, disease).","why":"Limiting factors limit population size."},{"lesson":"A3","scen":true,"type":"mc","q":"In a forest, the hare population rises sharply one year and the lynx population rises the next year. What best explains the lynx increase?","a":"More hares meant more food for lynx","wrong":["Lynx eat plants, which grew more","Hares hunt lynx","Lynx and hares compete for grass"],"why":"Predator numbers often follow prey numbers."},{"lesson":"A3","scen":true,"type":"mc","q":"Yeast in a flask of sugar water grows fast for a few days, then its population stops increasing. What is the most likely reason?","a":"Food (sugar) and space became limiting","wrong":["The yeast became a predator","Yeast needs no food","The flask got more sugar each day"],"why":"Resources run out, so growth levels off."},{"lesson":"A3","scen":true,"type":"tf","q":"Bees get nectar from flowers while carrying pollen that helps the plants reproduce, so this is mutualism.","a":"True","why":"Both the bee and the flower benefit."},{"lesson":"A3","scen":true,"type":"short","q":"An introduced beetle eats the same leaves as a native beetle. Predict what may happen to the native beetle population and explain why.","groups":[["decreas","declin","fall","drop","fewer","less"],["compet","food","leaves"]],"a":"It may decrease because the two beetles compete for the same leaves, leaving less food for the native beetle.","why":"Competition for a limited resource can reduce a population."},{"lesson":"A3","scen":true,"type":"fill","q":"A deer population grows to 500 and then stays near 500 for many years. 500 is close to the habitat’s ___ ___.","alts":["carrying capacity"],"a":"carrying capacity","why":"A population that levels off is near carrying capacity."},{"lesson":"A3","scen":true,"type":"mc","q":"Remoras ride on sharks and eat their leftover scraps without helping or harming the shark. This is","a":"commensalism","wrong":["mutualism","parasitism","predation"],"why":"The remora benefits; the shark is unaffected."},{"lesson":"A3","scen":true,"type":"mc","q":"After wolves were removed from a park, the elk population boomed and then crashed. Why did it crash?","a":"The elk ate more plants than could regrow, so food became limiting","wrong":["Wolves returned instantly","Elk do not need food","Elk turned into a different species"],"why":"Without predators, elk overshot the food supply."}]},{"id":"A4","title":"Food Chains, Food Webs and Energy","qs":[{"lesson":"A4","scen":false,"type":"mc","q":"Which organism is a producer?","a":"Grass","wrong":["Rabbit","Mushroom","Hawk"],"why":"Producers make their own food by photosynthesis."},{"lesson":"A4","scen":false,"type":"mc","q":"In a food web, the arrows point","a":"from the organism eaten to the organism that eats it","wrong":["from the eater to the food","from the sun to decomposers only","in random directions"],"why":"Arrows show the direction energy and matter move."},{"lesson":"A4","scen":false,"type":"mc","q":"Which organisms break down dead plants and animals and return nutrients to the soil?","a":"Decomposers","wrong":["Producers","Herbivores","Carnivores"],"why":"Fungi and bacteria are decomposers."},{"lesson":"A4","scen":false,"type":"tf","q":"An omnivore eats both plants and animals.","a":"True","why":"Bears and humans are omnivores."},{"lesson":"A4","scen":false,"type":"tf","q":"All of the energy in grass is passed on to the rabbit that eats it.","a":"False","why":"Only about 10% passes on; the rest is used for life processes or lost as heat."},{"lesson":"A4","scen":false,"type":"fill","q":"An animal that eats only plants is called an ___.","alts":["herbivore"],"a":"herbivore","why":"Herbi- means plant eating."},{"lesson":"A4","scen":false,"type":"fill","q":"About ___ percent of the energy at one level of an energy pyramid passes to the next level.","alts":["10","ten"],"a":"10","why":"The 10% rule."},{"lesson":"A4","scen":false,"type":"short","q":"Why are there usually fewer top predators than herbivores in an ecosystem?","groups":[["energy"],["less","lost","10","heat","decrease","little"]],"a":"Energy decreases at each level (only about 10% is passed on), so there is only enough energy to support a few top predators.","why":"The energy pyramid narrows at the top."},{"lesson":"A4","scen":true,"type":"mc","q":"A barn owl pellet contains 5 vole skulls, 2 shrew skulls and 1 bird skull. What can you conclude?","a":"Voles are probably a large part of this owl’s diet","wrong":["The owl eats only birds","The owl is a producer","Shrews ate the voles"],"why":"The pellet is direct evidence of what the owl ate."},{"lesson":"A4","scen":true,"type":"mc","q":"In the chain grass → grasshopper → frog → snake, the grass has 20,000 units of energy. About how much reaches the frog?","a":"200 units","wrong":["2,000 units","20,000 units","20 units"],"why":"20,000 × 10% = 2,000 for the grasshopper; × 10% = 200 for the frog."},{"lesson":"A4","scen":true,"type":"tf","q":"If a disease kills most frogs in a pond, the snakes that eat frogs may decline and the insects frogs eat may increase.","a":"True","why":"Changes ripple through a food web in both directions."},{"lesson":"A4","scen":true,"type":"short","q":"A new fish that eats algae is added to a lake where snails also eat algae. Use a food web idea to predict one effect.","groups":[["snail"],["fewer","decreas","less","compet","declin","food"]],"a":"The snails may decrease because they compete with the new fish for algae.","why":"Adding a species can change other populations through competition."},{"lesson":"A4","scen":true,"type":"fill","q":"In the chain algae → small fish → large fish → heron, the heron is a(n) ___ (carnivore, herbivore or producer).","alts":["carnivore"],"a":"carnivore","why":"The heron eats fish, so it is a carnivore."},{"lesson":"A4","scen":true,"type":"mc","q":"A student models a food web with yarn connecting cards. She removes the “mouse” card. Which card is most likely affected directly?","a":"Snake, which eats mice","wrong":["Sun","Rocks","Water"],"why":"Animals that eat mice lose a food source."}]},{"id":"A5","title":"Photosynthesis, Cellular Respiration and Cycling of Matter","qs":[{"lesson":"A5","scen":false,"type":"mc","q":"What are the products of photosynthesis?","a":"Sugar and oxygen","wrong":["Carbon dioxide and water","Oxygen and carbon dioxide","Sugar and carbon dioxide"],"why":"Photosynthesis makes glucose and releases oxygen."},{"lesson":"A5","scen":false,"type":"mc","q":"Where in a plant cell does photosynthesis happen?","a":"Chloroplast","wrong":["Mitochondrion","Nucleus","Cell wall"],"why":"Chloroplasts contain chlorophyll that captures light."},{"lesson":"A5","scen":false,"type":"mc","q":"Which process releases energy from sugar in nearly all living cells?","a":"Cellular respiration","wrong":["Photosynthesis","Evaporation","Condensation"],"why":"Respiration releases stored chemical energy."},{"lesson":"A5","scen":false,"type":"tf","q":"Plants carry out cellular respiration as well as photosynthesis.","a":"True","why":"Plants also need to release energy from sugar, day and night."},{"lesson":"A5","scen":false,"type":"tf","q":"Energy is recycled in an ecosystem in the same way as carbon atoms.","a":"False","why":"Matter is recycled; energy flows in from the sun and leaves as heat."},{"lesson":"A5","scen":false,"type":"fill","q":"Cellular respiration uses oxygen and sugar and gives off carbon dioxide and ___.","alts":["water"],"a":"water","why":"Respiration products: CO₂ and water, plus energy."},{"lesson":"A5","scen":false,"type":"fill","q":"Producers capture energy from ___ to make sugar.","alts":["sunlight","light","the sun","sun"],"a":"sunlight","why":"Light is the energy source for photosynthesis."},{"lesson":"A5","scen":false,"type":"short","q":"Explain how a carbon atom in the air could end up in your muscles.","groups":[["plant","photosynth"],["eat","food","ate"]],"a":"A plant takes in the carbon dioxide during photosynthesis and builds it into sugar; you eat the plant (or an animal that ate it) and your body uses that carbon to build muscle.","why":"Carbon cycles from air to producers to consumers."},{"lesson":"A5","scen":true,"type":"mc","q":"Blue BTB solution turns yellow after a student breathes into it through a straw. What gas caused the change?","a":"Carbon dioxide","wrong":["Oxygen","Nitrogen","Helium"],"why":"BTB changes color when carbon dioxide dissolves in it."},{"lesson":"A5","scen":true,"type":"mc","q":"A tube with water plant and yellow BTB (high CO₂) is left in bright light and turns blue. What happened?","a":"The plant used up CO₂ during photosynthesis","wrong":["The plant released more CO₂","The light added oxygen to the BTB","The BTB evaporated"],"why":"Removing CO₂ makes BTB go back to blue."},{"lesson":"A5","scen":true,"type":"tf","q":"A sealed jar with a plant and a snail kept in the light could support both for a while because their gases are exchanged.","a":"True","why":"The plant supplies oxygen and sugar; the snail gives off CO₂ the plant uses."},{"lesson":"A5","scen":true,"type":"short","q":"A plant is kept in total darkness for a week. Which process stops and which continues? Explain.","groups":[["photosynth"],["stop"]],"a":"Photosynthesis stops because there is no light, but cellular respiration continues because the plant still needs energy.","why":"Respiration does not need light."},{"lesson":"A5","scen":true,"type":"fill","q":"When a log rots, decomposers release carbon back into the air as ___ ___.","alts":["carbon dioxide","co2","co₂"],"a":"carbon dioxide","why":"Decomposers respire, releasing CO₂."},{"lesson":"A5","scen":true,"type":"mc","q":"Which change would most likely raise the amount of carbon dioxide in the air?","a":"Cutting down and burning a large forest","wrong":["Planting many trees","Growing more algae in the ocean","Protecting wetlands"],"why":"Burning releases stored carbon and removes producers that absorb CO₂."}]}]},"2":{"num":2,"letter":"B","title":"Geological Processes","lessons":[{"id":"B1","title":"Choosing a Safe Site: Groundwater and Landslides","qs":[{"lesson":"B1","scen":false,"type":"mc","q":"What is groundwater?","a":"Water that fills spaces in soil and rock underground","wrong":["Water in rivers only","Water vapor in clouds","Ice on mountain tops"],"why":"Groundwater soaks into and moves through the ground."},{"lesson":"B1","scen":false,"type":"mc","q":"Which material lets water flow through most easily?","a":"Gravel","wrong":["Clay","Granite with no cracks","Packed shale"],"why":"Gravel has large connected spaces, so it is very permeable."},{"lesson":"B1","scen":false,"type":"mc","q":"Which slope is most at risk of a landslide?","a":"A steep hillside soaked by heavy rain after a wildfire removed the plants","wrong":["A flat field with grass","A gentle slope with many trees","A dry desert plain"],"why":"Steepness, water and lack of roots all raise risk."},{"lesson":"B1","scen":false,"type":"tf","q":"Clay has low permeability, so water moves through it slowly.","a":"True","why":"Clay’s tiny particles leave small, poorly connected spaces."},{"lesson":"B1","scen":false,"type":"tf","q":"A good nuclear waste site should have lots of fast-moving groundwater.","a":"False","why":"Moving groundwater could carry leaking waste to people."},{"lesson":"B1","scen":false,"type":"fill","q":"How easily water flows through a material is its ___.","alts":["permeability"],"a":"permeability","why":"Permeability describes flow; porosity describes storage space."},{"lesson":"B1","scen":false,"type":"fill","q":"A layer of underground rock or sediment that holds usable groundwater is called an ___.","alts":["aquifer"],"a":"aquifer","why":"Wells draw water from aquifers."},{"lesson":"B1","scen":false,"type":"short","q":"Why do plant roots help prevent landslides?","groups":[["hold","bind","anchor","grip","root"]],"a":"Roots hold soil particles together and soak up water, keeping the slope stable.","why":"Vegetation stabilizes slopes."},{"lesson":"B1","scen":true,"type":"mc","q":"Water poured into cups of sand, gravel and clay drains fastest through gravel and slowest through clay. Which layer would best keep leaking waste from reaching groundwater?","a":"Clay","wrong":["Gravel","Sand","They would all work equally"],"why":"Low-permeability clay slows water and anything dissolved in it."},{"lesson":"B1","scen":true,"type":"mc","q":"A town is choosing between two waste sites. Site 1 is on stable rock in a dry desert far from faults. Site 2 is near a river on a fault. Which is safer and why?","a":"Site 1, because it is dry and far from earthquakes","wrong":["Site 2, because water cools the waste","Site 2, because faults are stable","They are equally safe"],"why":"Dry, stable ground away from faults lowers risk."},{"lesson":"B1","scen":true,"type":"tf","q":"A model hillside of wet sand collapses at a lower angle than one of dry sand. This suggests water increases landslide risk.","a":"True","why":"Water adds weight and reduces friction between grains."},{"lesson":"B1","scen":true,"type":"short","q":"A farmer’s well is downhill from a leaking chemical tank. Explain how the chemicals might reach the well.","groups":[["ground","water"],["soak","flow","carr","move","seep","dissolv"]],"a":"Rain soaks into the ground, dissolves the chemicals and the groundwater carries them downhill through permeable soil into the well.","why":"Groundwater can transport pollutants."},{"lesson":"B1","scen":true,"type":"fill","q":"A geologist says a site has “high porosity but low permeability.” This means the rock holds a lot of water but water ___ through it slowly.","alts":["flows","moves","passes","travels"],"a":"flows","why":"Porosity = storage; permeability = flow."},{"lesson":"B1","scen":true,"type":"mc","q":"Which evidence would best show that a hillside is slowly sliding?","a":"Tilted fence posts and cracked walls on the slope","wrong":["A rainbow above the hill","A new tree being planted","Clear skies for a week"],"why":"Tilted objects and cracks are evidence of ground movement."}]},{"id":"B2","title":"Earthquakes and Volcanoes","qs":[{"lesson":"B2","scen":false,"type":"mc","q":"What causes an earthquake?","a":"Rocks suddenly slipping along a fault","wrong":["Strong winds","The Moon pulling on the ocean","Heavy rain"],"why":"Built-up stress is released when rocks slip."},{"lesson":"B2","scen":false,"type":"mc","q":"Where do most earthquakes and volcanoes occur?","a":"Along plate boundaries","wrong":["In the exact center of plates","Only near the North Pole","Randomly across Earth"],"why":"Mapping shows they form belts along plate boundaries."},{"lesson":"B2","scen":false,"type":"mc","q":"What is the epicenter?","a":"The point on the surface right above where the earthquake starts","wrong":["The deepest part of a volcano","The center of Earth","The place with the least shaking"],"why":"The epicenter is above the focus."},{"lesson":"B2","scen":false,"type":"tf","q":"Molten rock is called lava once it reaches Earth’s surface.","a":"True","why":"Underground it is magma; at the surface it is lava."},{"lesson":"B2","scen":false,"type":"tf","q":"Scientists can predict the exact day and hour of most earthquakes.","a":"False","why":"They can estimate risk and probability, not exact times."},{"lesson":"B2","scen":false,"type":"fill","q":"The belt of volcanoes and earthquakes around the Pacific Ocean is called the Ring of ___.","alts":["fire"],"a":"fire","why":"The Ring of Fire follows Pacific plate boundaries."},{"lesson":"B2","scen":false,"type":"fill","q":"A huge ocean wave caused by an undersea earthquake is a ___.","alts":["tsunami"],"a":"tsunami","why":"Tsunamis can cross whole oceans."},{"lesson":"B2","scen":false,"type":"short","q":"Why are some volcanic eruptions explosive?","groups":[["thick","viscous","sticky","gas"]],"a":"The magma is thick (viscous) and full of gas, so pressure builds until it bursts out explosively.","why":"Gas trapped in thick magma causes explosions."},{"lesson":"B2","scen":true,"type":"mc","q":"A student squeezes a bottle of thick honey with a straw blowing bubbles into it and a bottle of water the same way. The honey spurts violently. This models","a":"gas trapped in thick magma causing an explosive eruption","wrong":["runny lava flows","an earthquake fault","groundwater flow"],"why":"Thick fluids trap gas until pressure releases suddenly."},{"lesson":"B2","scen":true,"type":"mc","q":"Two cities have the same earthquake hazard. City X has old brick buildings; City Y has newer reinforced buildings. Which city has higher risk?","a":"City X","wrong":["City Y","Equal risk","Neither has any risk"],"why":"Risk depends on how vulnerable buildings and people are."},{"lesson":"B2","scen":true,"type":"tf","q":"If a new map shows many earthquakes along a line down the middle of an ocean, that line is probably a plate boundary.","a":"True","why":"Earthquake belts mark plate boundaries."},{"lesson":"B2","scen":true,"type":"short","q":"A coastal town is near a fault under the ocean. Name one hazard the town should prepare for and one way to prepare.","groups":[["tsunami","shak","landslide"],["warn","evacu","high ground","drill","build","reinforc","plan","siren"]],"a":"A tsunami; set up warning sirens and evacuation routes to high ground.","why":"Undersea earthquakes can cause tsunamis."},{"lesson":"B2","scen":true,"type":"fill","q":"An earthquake map shows almost no earthquakes in the middle of a large plate. A good place to store waste would be ___ (near / far from) plate boundaries.","alts":["far from","far"],"a":"far from","why":"Plate interiors have fewer earthquakes and volcanoes."},{"lesson":"B2","scen":true,"type":"mc","q":"During a model earthquake on a shake table, which tower stays standing longest?","a":"One with a wide base and cross-bracing","wrong":["A tall, thin tower with no bracing","A tower built on loose sand","A tower glued at the top only"],"why":"A wide base and bracing resist shaking."}]},{"id":"B3","title":"Earth’s Moving Surface and Inner Layers","qs":[{"lesson":"B3","scen":false,"type":"mc","q":"Which is Earth’s thinnest layer?","a":"Crust","wrong":["Mantle","Outer core","Inner core"],"why":"The crust is like the skin on an apple."},{"lesson":"B3","scen":false,"type":"mc","q":"Which layer is liquid?","a":"Outer core","wrong":["Inner core","Crust","Lithosphere"],"why":"The outer core is liquid iron and nickel."},{"lesson":"B3","scen":false,"type":"mc","q":"The lithosphere is made of","a":"the crust and the uppermost mantle","wrong":["the inner and outer core","only the oceans","the asthenosphere only"],"why":"The rigid lithosphere is broken into plates."},{"lesson":"B3","scen":false,"type":"tf","q":"The inner core is solid even though it is extremely hot.","a":"True","why":"Enormous pressure keeps it solid."},{"lesson":"B3","scen":false,"type":"tf","q":"Tectonic plates move several meters every day.","a":"False","why":"They move a few centimeters per year."},{"lesson":"B3","scen":false,"type":"fill","q":"The soft, slowly flowing layer that plates ride on is the ___.","alts":["asthenosphere"],"a":"asthenosphere","why":"Astheno- means weak."},{"lesson":"B3","scen":false,"type":"fill","q":"The thick layer of hot rock between the crust and the core is the ___.","alts":["mantle"],"a":"mantle","why":"The mantle is Earth’s largest layer by volume."},{"lesson":"B3","scen":false,"type":"short","q":"How do scientists know about Earth’s inner layers if no one has drilled there?","groups":[["seismic","earthquake wave","wave"]],"a":"They study how seismic waves from earthquakes change speed and bend as they pass through different layers.","why":"Seismic waves are the main evidence."},{"lesson":"B3","scen":true,"type":"mc","q":"A GPS station in California moves 5 cm northwest each year. How far will it move in 20 years?","a":"100 cm (1 meter)","wrong":["25 cm","5 cm","1,000 cm"],"why":"5 cm × 20 = 100 cm."},{"lesson":"B3","scen":true,"type":"mc","q":"A model of Earth uses a peach. Which part best models the crust?","a":"The thin skin","wrong":["The pit","The juicy fruit","The stem"],"why":"The thin skin, like the crust, is a tiny fraction of the whole."},{"lesson":"B3","scen":true,"type":"tf","q":"If S-waves (which cannot pass through liquids) do not reach the far side of Earth, this is evidence of a liquid layer inside.","a":"True","why":"The shadow of S-waves revealed the liquid outer core."},{"lesson":"B3","scen":true,"type":"short","q":"Two GPS stations on opposite sides of a fault move in opposite directions each year. What does this tell you?","groups":[["plate","move"],["opposite","different","boundary","apart","past"]],"a":"The stations are on two different plates that are moving past each other along the fault (a plate boundary).","why":"Different motion reveals a boundary."},{"lesson":"B3","scen":true,"type":"fill","q":"Going deeper into Earth, both temperature and pressure ___.","alts":["increase","go up","rise"],"a":"increase","why":"Both rise with depth."},{"lesson":"B3","scen":true,"type":"mc","q":"A drill sample from the ocean floor would most likely be","a":"oceanic crust that is thin and dense","wrong":["liquid iron","part of the inner core","continental crust that is very thick"],"why":"Ocean floors are made of thin, dense oceanic crust."}]},{"id":"B4","title":"Plate Tectonics","qs":[{"lesson":"B4","scen":false,"type":"mc","q":"What happens at a divergent boundary?","a":"Plates move apart and new crust forms","wrong":["Plates collide and form mountains","Plates slide past each other","Plates stop moving"],"why":"Divergent = diverge, move apart."},{"lesson":"B4","scen":false,"type":"mc","q":"The San Andreas Fault is an example of which kind of boundary?","a":"Transform","wrong":["Divergent","Convergent","Hot spot"],"why":"The Pacific and North American plates slide past each other."},{"lesson":"B4","scen":false,"type":"mc","q":"Which is evidence that continents were once joined?","a":"The same fossil species found on continents now separated by ocean","wrong":["Continents have different climates today","Oceans are salty","Mountains exist"],"why":"Land animals could not have swum across oceans."},{"lesson":"B4","scen":false,"type":"tf","q":"At a convergent boundary between an ocean plate and a continent, the denser ocean plate sinks under the continent.","a":"True","why":"This is subduction, which forms a trench and volcanoes."},{"lesson":"B4","scen":false,"type":"tf","q":"The rocks of the seafloor are oldest at the mid-ocean ridge.","a":"False","why":"They are youngest at the ridge, where new crust forms."},{"lesson":"B4","scen":false,"type":"fill","q":"The supercontinent that broke apart to form today’s continents is called ___.","alts":["pangaea","pangea"],"a":"pangaea","why":"Pangaea broke up about 200 million years ago."},{"lesson":"B4","scen":false,"type":"fill","q":"Hot mantle rock rising and cool rock sinking forms ___ currents that help move plates.","alts":["convection"],"a":"convection","why":"Convection transfers heat and moves plates."},{"lesson":"B4","scen":false,"type":"short","q":"Name two pieces of evidence for plate tectonics.","groups":[["fossil","coast","puzzle","fit","rock","seafloor","ridge","earthquake","volcano","age","magnet","gps"],["fossil","coast","puzzle","fit","rock","seafloor","ridge","earthquake","volcano","age","magnet","gps"]],"a":"Matching fossils on separate continents and the way coastlines like South America and Africa fit together.","why":"Multiple lines of evidence support the theory."},{"lesson":"B4","scen":true,"type":"mc","q":"A heated pot of thick soup has small crackers floating on top. The crackers drift apart above the hottest spot. This models","a":"plates moving because of mantle convection","wrong":["an earthquake","erosion by rivers","the rock cycle"],"why":"Rising warm material spreads out and carries the crackers like plates."},{"lesson":"B4","scen":true,"type":"mc","q":"The Himalayas are still rising. Which boundary is most likely there?","a":"Convergent (two continental plates colliding)","wrong":["Divergent","Transform","No boundary"],"why":"Colliding continents crumple upward into mountains."},{"lesson":"B4","scen":true,"type":"tf","q":"If a seafloor sample 500 km from a ridge is older than a sample 100 km from the ridge, this supports seafloor spreading.","a":"True","why":"Crust ages with distance from the ridge where it formed."},{"lesson":"B4","scen":true,"type":"short","q":"Iceland sits on the Mid-Atlantic Ridge and is slowly getting wider. Explain why.","groups":[["apart","diverg","spread"],["new","magma","crust","lava"]],"a":"It sits on a divergent boundary where the plates pull apart, and magma rises to form new crust in the gap.","why":"Divergent boundaries add new crust."},{"lesson":"B4","scen":true,"type":"fill","q":"Plates move about 2.5 cm per year. In 4 million years a plate would move about ___ km.","alts":["100"],"a":"100","why":"2.5 cm × 4,000,000 = 10,000,000 cm = 100 km."},{"lesson":"B4","scen":true,"type":"mc","q":"A chain of volcanoes lies along the coast next to a deep ocean trench. What is happening?","a":"An ocean plate is subducting under a continental plate","wrong":["Two plates are sliding past each other","Plates are moving apart","The continent is sinking"],"why":"Subduction makes a trench and melted rock feeds volcanoes."}]},{"id":"B5","title":"The Rock Cycle and Earth’s Resources","qs":[{"lesson":"B5","scen":false,"type":"mc","q":"Which rock forms when lava or magma cools?","a":"Igneous","wrong":["Sedimentary","Metamorphic","Fossil"],"why":"Igne- means fire."},{"lesson":"B5","scen":false,"type":"mc","q":"Which rock forms from layers of sediment pressed and cemented together?","a":"Sedimentary","wrong":["Igneous","Metamorphic","Magma"],"why":"Sediments compact and cement."},{"lesson":"B5","scen":false,"type":"mc","q":"Marble forms when limestone is exposed to heat and pressure. Marble is","a":"metamorphic","wrong":["igneous","sedimentary","a mineral only"],"why":"Heat and pressure change rock into metamorphic rock."},{"lesson":"B5","scen":false,"type":"tf","q":"A rock can only move through the rock cycle in one fixed order.","a":"False","why":"Rocks can take many paths; any type can become any other."},{"lesson":"B5","scen":false,"type":"tf","q":"Fossils are most often found in sedimentary rock.","a":"True","why":"Organisms are buried in sediment that becomes rock."},{"lesson":"B5","scen":false,"type":"fill","q":"Breaking rock into smaller pieces is ___; carrying the pieces away is erosion.","alts":["weathering"],"a":"weathering","why":"Weathering breaks; erosion moves."},{"lesson":"B5","scen":false,"type":"fill","q":"A resource like copper ore that forms over millions of years is ___ on human time scales.","alts":["nonrenewable","non-renewable"],"a":"nonrenewable","why":"It cannot be replaced as fast as we use it."},{"lesson":"B5","scen":false,"type":"short","q":"Why do some igneous rocks have large crystals and others tiny crystals?","groups":[["cool"],["slow","fast","quick","time"]],"a":"Rocks that cooled slowly underground had time to grow large crystals; lava that cooled quickly at the surface formed tiny crystals.","why":"Cooling rate controls crystal size."},{"lesson":"B5","scen":true,"type":"mc","q":"A rock has visible layers and a shell fossil. It most likely formed","a":"from sediments deposited in water","wrong":["from cooling lava","from intense heat melting it","in the inner core"],"why":"Layers and fossils point to sedimentary rock."},{"lesson":"B5","scen":true,"type":"mc","q":"Crayon shavings are pressed together into a layered block, then warmed and squeezed until the layers bend. The bent block models","a":"metamorphic rock","wrong":["igneous rock","sediment","magma"],"why":"Heat and pressure without full melting model metamorphism."},{"lesson":"B5","scen":true,"type":"tf","q":"Recycling aluminum cans reduces the need to mine new bauxite ore.","a":"True","why":"Recycled metal replaces newly mined ore."},{"lesson":"B5","scen":true,"type":"short","q":"A country has rich copper deposits but nearby rivers are polluted by mining waste. Describe one trade-off the country faces.","groups":[["money","job","econom","income"],["pollut","environment","water","health","river"]],"a":"Mining brings jobs and income but pollutes rivers and harms health and ecosystems.","why":"Resource decisions involve trade-offs."},{"lesson":"B5","scen":true,"type":"fill","q":"Granite with large crystals most likely cooled ___ (slowly / quickly) deep underground.","alts":["slowly"],"a":"slowly","why":"Large crystals mean slow cooling."},{"lesson":"B5","scen":true,"type":"mc","q":"A town uses 10 tons of gravel a year, and its quarry holds 200 tons. If use doesn’t change, how long will the gravel last?","a":"20 years","wrong":["10 years","2 years","2,000 years"],"why":"200 ÷ 10 = 20."}]}]},"3":{"num":3,"letter":"C","title":"Chemistry of Materials","lessons":[{"id":"C1","title":"Materials and Elements","qs":[{"lesson":"C1","scen":false,"type":"mc","q":"What is an element?","a":"A pure substance made of only one kind of atom","wrong":["Any mixture of two substances","A liquid at room temperature","A kind of plastic"],"why":"Elements can’t be broken down chemically into simpler substances."},{"lesson":"C1","scen":false,"type":"mc","q":"Which property is typical of metals?","a":"Good conductor of electricity","wrong":["Brittle","Dull","Poor conductor of heat"],"why":"Metals conduct heat and electricity well."},{"lesson":"C1","scen":false,"type":"mc","q":"The symbol Fe stands for","a":"iron","wrong":["fluorine","francium","lead"],"why":"Fe comes from the Latin “ferrum”."},{"lesson":"C1","scen":false,"type":"tf","q":"Elements in the same column of the periodic table tend to have similar properties.","a":"True","why":"Groups share properties."},{"lesson":"C1","scen":false,"type":"tf","q":"Plastic is an element.","a":"False","why":"Plastics are made of molecules containing several elements, mostly carbon and hydrogen."},{"lesson":"C1","scen":false,"type":"fill","q":"Anything that has mass and takes up space is called ___.","alts":["matter"],"a":"matter","why":"Matter has mass and volume."},{"lesson":"C1","scen":false,"type":"fill","q":"A material that lets electricity pass through easily is a good ___.","alts":["conductor"],"a":"conductor","why":"Metals are good conductors."},{"lesson":"C1","scen":false,"type":"short","q":"Why are cooking pots often made of metal but have plastic or wooden handles?","groups":[["metal"],["conduct","heat"],["handle","plastic","wood"]],"a":"Metal conducts heat well to cook food, while plastic or wood handles are poor conductors so they stay cool to touch.","why":"Materials are matched to their job."},{"lesson":"C1","scen":true,"type":"mc","q":"A sample is shiny, bends without breaking and lights a bulb in a circuit. It is most likely a","a":"metal","wrong":["nonmetal","plastic","glass"],"why":"Shiny, malleable and conductive point to a metal."},{"lesson":"C1","scen":true,"type":"mc","q":"An engineer needs a material for electrical wire. Which property matters most?","a":"Conducts electricity well","wrong":["Is transparent","Is brittle","Floats on water"],"why":"Wires must carry current."},{"lesson":"C1","scen":true,"type":"tf","q":"A yellow powder that crumbles when tapped and doesn’t conduct electricity is likely a nonmetal like sulfur.","a":"True","why":"Brittle, dull and nonconducting match nonmetals."},{"lesson":"C1","scen":true,"type":"short","q":"You test five unknown solids. Describe two tests you could do to decide whether each is a metal.","groups":[["conduct","circuit","bulb","electric"],["shin","luster","bend","malleab","hammer","heat"]],"a":"Test whether it conducts electricity in a circuit and whether it is shiny and bends when hammered.","why":"Metals share testable properties."},{"lesson":"C1","scen":true,"type":"fill","q":"Elements in the same ___ (row / column) of the periodic table have similar properties.","alts":["column"],"a":"column","why":"Columns are groups."},{"lesson":"C1","scen":true,"type":"mc","q":"Why might a bike frame be made of aluminum instead of iron?","a":"Aluminum is strong but lighter","wrong":["Aluminum is not a metal","Iron does not exist naturally","Aluminum conducts electricity"],"why":"Choosing materials involves properties like strength and weight."}]},{"id":"C2","title":"Physical and Chemical Properties; Density","qs":[{"lesson":"C2","scen":false,"type":"mc","q":"Which is a chemical property?","a":"Flammability","wrong":["Color","Density","Melting point"],"why":"Flammability describes how a substance reacts (burns)."},{"lesson":"C2","scen":false,"type":"mc","q":"Density is calculated as","a":"mass ÷ volume","wrong":["volume ÷ mass","mass × volume","mass + volume"],"why":"D = m/V."},{"lesson":"C2","scen":false,"type":"mc","q":"An object with density 0.8 g/mL is placed in water. It will","a":"float","wrong":["sink","dissolve","explode"],"why":"0.8 < 1 g/mL, so it floats."},{"lesson":"C2","scen":false,"type":"tf","q":"If you cut a block of pure aluminum in half, each half has the same density as the whole block.","a":"True","why":"Density is a characteristic property."},{"lesson":"C2","scen":false,"type":"tf","q":"Rusting is a physical property of iron.","a":"False","why":"Rusting forms a new substance, so it is a chemical property."},{"lesson":"C2","scen":false,"type":"fill","q":"A rock has a mass of 30 g and a volume of 10 cm³. Its density is ___ g/cm³.","alts":["3"],"a":"3","why":"30 ÷ 10 = 3."},{"lesson":"C2","scen":false,"type":"fill","q":"The density of water is about ___ g/mL.","alts":["1"],"a":"1","why":"Water: 1 g/mL."},{"lesson":"C2","scen":false,"type":"short","q":"Explain how you can find the volume of an irregular rock.","groups":[["water","displac"],["rise","differen","subtract","level"]],"a":"Put it in a graduated cylinder of water; the rise in water level (new reading minus old) is the rock’s volume.","why":"Water displacement."},{"lesson":"C2","scen":true,"type":"mc","q":"A liquid has mass 45 g and volume 50 mL. Will a cork with density 0.25 g/mL float in it?","a":"Yes; the liquid is 0.9 g/mL, denser than the cork","wrong":["No; the cork is denser","No; nothing floats in that liquid","Only if the cork is cut in half"],"why":"45 ÷ 50 = 0.9 g/mL > 0.25 g/mL."},{"lesson":"C2","scen":true,"type":"mc","q":"Two unknown metal cubes have densities of 8.9 g/cm³ and 2.7 g/cm³. Copper is 8.9 and aluminum is 2.7. Which statement is best supported?","a":"The first cube is probably copper and the second aluminum","wrong":["Both are copper","Density can’t identify metals","The bigger cube must be copper"],"why":"Density is a characteristic property used for identification."},{"lesson":"C2","scen":true,"type":"tf","q":"A student says a big log floats but a small pebble sinks, so heavy things float. This reasoning is correct.","a":"False","why":"Floating depends on density, not mass."},{"lesson":"C2","scen":true,"type":"short","q":"You need a material for a boat hull. Which two properties would you test and why?","groups":[["dens","float"],["strong","waterproof","absorb","rust","corro","hard","break"]],"a":"Density (it must float) and whether it absorbs water or corrodes (it must stay strong and waterproof).","why":"Pick properties that match the design need."},{"lesson":"C2","scen":true,"type":"fill","q":"A stone raises water in a cylinder from 40 mL to 52 mL and has a mass of 36 g. Its density is ___ g/mL.","alts":["3"],"a":"3","why":"Volume = 12 mL; 36 ÷ 12 = 3."},{"lesson":"C2","scen":true,"type":"mc","q":"Salt dissolves in water but sand doesn’t. Which property are you comparing?","a":"Solubility","wrong":["Flammability","Density","Conductivity"],"why":"Dissolving is solubility, a physical property."}]},{"id":"C3","title":"Atoms, Molecules and the Structure of Materials","qs":[{"lesson":"C3","scen":false,"type":"mc","q":"How many atoms are in one molecule of H₂O?","a":"3","wrong":["2","1","4"],"why":"2 hydrogen + 1 oxygen = 3."},{"lesson":"C3","scen":false,"type":"mc","q":"Which is a compound?","a":"Carbon dioxide (CO₂)","wrong":["Oxygen gas (O₂)","Iron (Fe)","Helium (He)"],"why":"CO₂ contains two different elements."},{"lesson":"C3","scen":false,"type":"mc","q":"What is the smallest particle of an element?","a":"An atom","wrong":["A molecule","A cell","A crystal"],"why":"Atoms are the building blocks of elements."},{"lesson":"C3","scen":false,"type":"tf","q":"Diamond and graphite are both made only of carbon atoms.","a":"True","why":"Their different arrangements give different properties."},{"lesson":"C3","scen":false,"type":"tf","q":"The formula O₂ represents a compound.","a":"False","why":"It contains only oxygen, so it is an element (as molecules)."},{"lesson":"C3","scen":false,"type":"fill","q":"In the formula CH₄, there are ___ hydrogen atoms.","alts":["4","four"],"a":"4","why":"The subscript 4 belongs to H."},{"lesson":"C3","scen":false,"type":"fill","q":"Two or more atoms joined together form a ___.","alts":["molecule"],"a":"molecule","why":"Molecules are groups of bonded atoms."},{"lesson":"C3","scen":false,"type":"short","q":"Why can two substances made of the same element have different properties?","groups":[["arrang","structure","connect","bond","pattern"]],"a":"Their atoms are arranged or connected in different ways, and structure determines properties.","why":"Structure → properties."},{"lesson":"C3","scen":true,"type":"mc","q":"A model has 1 black ball (C) connected to 2 red balls (O). Which formula does it show?","a":"CO₂","wrong":["C₂O","CO","O₂"],"why":"One carbon, two oxygens."},{"lesson":"C3","scen":true,"type":"mc","q":"Table salt forms cube-shaped crystals with a repeating pattern of sodium and chlorine. This is an example of","a":"an extended structure","wrong":["a single small molecule","a mixture","an element"],"why":"Salt is a repeating crystal lattice."},{"lesson":"C3","scen":true,"type":"tf","q":"Glucose, C₆H₁₂O₆, contains 24 atoms per molecule.","a":"True","why":"6 + 12 + 6 = 24."},{"lesson":"C3","scen":true,"type":"short","q":"A student builds ammonia, NH₃, with model kits. Describe her model.","groups":[["1","one","single"],["nitrogen"],["3","three"],["hydrogen"]],"a":"One nitrogen atom bonded to three hydrogen atoms.","why":"Read the subscripts."},{"lesson":"C3","scen":true,"type":"fill","q":"The formula for a molecule with two hydrogen atoms and two oxygen atoms is ___.","alts":["h2o2","h₂o₂"],"a":"h2o2","why":"That is hydrogen peroxide, H₂O₂."},{"lesson":"C3","scen":true,"type":"mc","q":"Pencil “lead” smears easily but diamond can cut glass. The best explanation is","a":"their carbon atoms are arranged differently","wrong":["pencil lead is actually lead metal","diamond is a mixture","graphite has no atoms"],"why":"Same atoms, different structure."}]},{"id":"C4","title":"States of Matter and Particle Motion","qs":[{"lesson":"C4","scen":false,"type":"mc","q":"In which state are particles farthest apart?","a":"Gas","wrong":["Solid","Liquid","They are equal"],"why":"Gas particles spread out to fill the container."},{"lesson":"C4","scen":false,"type":"mc","q":"What happens to particles when thermal energy is added?","a":"They move faster","wrong":["They stop moving","They get smaller","They disappear"],"why":"More energy, faster motion."},{"lesson":"C4","scen":false,"type":"mc","q":"Water vapor turning into liquid droplets on a cold glass is","a":"condensation","wrong":["evaporation","melting","freezing"],"why":"Gas → liquid is condensation."},{"lesson":"C4","scen":false,"type":"tf","q":"A melting ice cube is going through a chemical change.","a":"False","why":"It is still water; changes of state are physical changes."},{"lesson":"C4","scen":false,"type":"tf","q":"Particles in a solid still vibrate.","a":"True","why":"They vibrate in place."},{"lesson":"C4","scen":false,"type":"fill","q":"A liquid changing to a gas at its surface is called ___.","alts":["evaporation"],"a":"evaporation","why":"Evaporation can happen below boiling point."},{"lesson":"C4","scen":false,"type":"fill","q":"A 50 g ice cube melts completely. The water has a mass of ___ g.","alts":["50"],"a":"50","why":"Mass is conserved during a change of state."},{"lesson":"C4","scen":false,"type":"short","q":"Use the particle model to explain why a gas can be squeezed into a smaller space but a solid cannot.","groups":[["far apart","space","gap","spread"]],"a":"Gas particles are far apart with lots of empty space between them, so they can be pushed closer; solid particles are already packed tightly.","why":"Particle spacing explains compressibility."},{"lesson":"C4","scen":true,"type":"mc","q":"A balloon put in the freezer shrinks. Why?","a":"The gas particles slow down and hit the balloon less hard","wrong":["Air leaks out through the rubber instantly","The particles get smaller","The balloon melts"],"why":"Cooling slows particles, lowering pressure."},{"lesson":"C4","scen":true,"type":"mc","q":"A sealed bag of ice (100 g total) melts on a scale. What does the scale show afterward?","a":"100 g","wrong":["Less than 100 g","More than 100 g","0 g"],"why":"Mass is conserved; nothing entered or left."},{"lesson":"C4","scen":true,"type":"tf","q":"A puddle disappearing on a sunny day is evidence that liquid particles can gain enough energy to become a gas.","a":"True","why":"That is evaporation."},{"lesson":"C4","scen":true,"type":"short","q":"Food coloring spreads faster in hot water than in cold water. Explain using particles.","groups":[["faster","more energy","quick","speed"]],"a":"Particles in hot water move faster, so they mix the coloring through the water more quickly.","why":"Temperature relates to particle speed."},{"lesson":"C4","scen":true,"type":"fill","q":"A student heats ice and records 0 °C for several minutes while it melts. During melting the temperature stays ___.","alts":["the same","constant","steady","0","0 °c","same"],"a":"the same","why":"Energy goes into changing the state, not raising temperature."},{"lesson":"C4","scen":true,"type":"mc","q":"Which drawing best shows liquid water particles?","a":"Particles close together but in a jumbled, sliding arrangement","wrong":["Particles in a perfect fixed grid","Particles very far apart","No particles at all"],"why":"Liquids: close and able to slide."}]},{"id":"C5","title":"Polymers and Plastics","qs":[{"lesson":"C5","scen":false,"type":"mc","q":"What is a monomer?","a":"A small repeating unit that links to form a polymer","wrong":["A very long chain of molecules","A kind of metal","A mixture of plastics"],"why":"Mono- means one unit."},{"lesson":"C5","scen":false,"type":"mc","q":"Which is a natural polymer?","a":"Cellulose in wood","wrong":["Polyethylene","Nylon","Polystyrene foam"],"why":"Cellulose is made by plants."},{"lesson":"C5","scen":false,"type":"mc","q":"Adding more cross-links between polymer chains usually makes the material","a":"stiffer and less stretchy","wrong":["more liquid","disappear","a metal"],"why":"Cross-links hold chains in place."},{"lesson":"C5","scen":false,"type":"tf","q":"Most plastics are synthetic polymers.","a":"True","why":"They are made by people, mostly from petroleum."},{"lesson":"C5","scen":false,"type":"tf","q":"Plastic bottles break down completely in a few weeks in the ocean.","a":"False","why":"Many plastics last hundreds of years, breaking into microplastics."},{"lesson":"C5","scen":false,"type":"fill","q":"A material that can be broken down by bacteria and other living things is ___.","alts":["biodegradable"],"a":"biodegradable","why":"Bio- life; degrade breaks down."},{"lesson":"C5","scen":false,"type":"fill","q":"A polymer is a long chain of repeating units called ___.","alts":["monomers"],"a":"monomers","why":"Monomers are the links."},{"lesson":"C5","scen":false,"type":"short","q":"Give one benefit and one problem of plastics for society.","groups":[["cheap","light","durab","strong","waterproof","useful","cost"],["pollut","litter","ocean","landfill","waste","break down","animal"]],"a":"They are cheap and durable, but they create long-lasting litter that pollutes oceans and harms animals.","why":"Plastics involve trade-offs."},{"lesson":"C5","scen":true,"type":"mc","q":"Glue mixed with borax becomes a stretchy slime. The borax most likely","a":"cross-links the glue’s polymer chains","wrong":["turns the glue into a metal","melts the glue","removes all the water instantly"],"why":"Borax links chains together."},{"lesson":"C5","scen":true,"type":"mc","q":"Students model a polymer with paper clips. Which change models a longer polymer?","a":"Adding more clips to the chain","wrong":["Removing clips","Painting the clips","Bending one clip"],"why":"More monomers = longer chain."},{"lesson":"C5","scen":true,"type":"tf","q":"If a city bans single-use plastic bags, it faces a trade-off between convenience and less litter.","a":"True","why":"Decisions weigh benefits and costs."},{"lesson":"C5","scen":true,"type":"short","q":"A company wants a cup that keeps drinks hot but won’t pollute for centuries. Suggest a material choice and explain.","groups":[["paper","biodegradab","plant","reusable","compost","metal","glass","ceramic"]],"a":"A reusable steel or ceramic mug, or a biodegradable plant-based cup, so it isn’t thrown away as long-lasting plastic.","why":"Design with environmental criteria."},{"lesson":"C5","scen":true,"type":"fill","q":"A slime with more borax is less stretchy because it has more ___-links.","alts":["cross"],"a":"cross","why":"More cross-links = stiffer."},{"lesson":"C5","scen":true,"type":"mc","q":"Which plan most reduces plastic waste from a school cafeteria?","a":"Switching to reusable trays and utensils","wrong":["Using thicker plastic forks","Throwing plastic in regular trash","Buying more plastic bags"],"why":"Reuse cuts waste at the source."}]}]},"4":{"num":4,"letter":"D","title":"Chemical Reactions","lessons":[{"id":"D1","title":"Evidence of Chemical Change","qs":[{"lesson":"D1","scen":false,"type":"mc","q":"Which is evidence of a chemical change?","a":"A solid forms when two clear liquids are mixed","wrong":["Ice melting","Sugar dissolving in water","Paper being cut"],"why":"A precipitate is a new substance."},{"lesson":"D1","scen":false,"type":"mc","q":"Which is a physical change?","a":"Breaking a glass","wrong":["Burning wood","Rusting iron","Baking a cake"],"why":"Breaking only changes shape."},{"lesson":"D1","scen":false,"type":"mc","q":"In a chemical reaction, the starting substances are called","a":"reactants","wrong":["products","precipitates","solutions"],"why":"Reactants react to form products."},{"lesson":"D1","scen":false,"type":"tf","q":"Dissolving salt in water is a chemical change.","a":"False","why":"The salt is still salt; dissolving is a physical change."},{"lesson":"D1","scen":false,"type":"tf","q":"Bubbles of gas forming when two liquids are mixed can be evidence of a chemical reaction.","a":"True","why":"A new gas may have formed."},{"lesson":"D1","scen":false,"type":"fill","q":"A solid that forms when two solutions are mixed is called a ___.","alts":["precipitate"],"a":"precipitate","why":"Precipitates indicate a reaction."},{"lesson":"D1","scen":false,"type":"fill","q":"The new substances made in a chemical reaction are called ___.","alts":["products"],"a":"products","why":"Products form from reactants."},{"lesson":"D1","scen":false,"type":"short","q":"List two kinds of evidence that a chemical reaction has happened.","groups":[["gas","bubble","color","colour","precipitate","solid","temperature","heat","cold","light","odor","smell"],["gas","bubble","color","colour","precipitate","solid","temperature","heat","cold","light","odor","smell"]],"a":"A gas forming (bubbles) and a color change (also precipitate or temperature change).","why":"Common evidence of chemical change."},{"lesson":"D1","scen":true,"type":"mc","q":"Baking soda and vinegar are mixed; the cup fizzes and gets colder. What can you conclude?","a":"A chemical reaction likely happened, producing a gas","wrong":["Only a physical change happened","Nothing happened","The vinegar froze"],"why":"Gas and temperature change are evidence of reaction."},{"lesson":"D1","scen":true,"type":"mc","q":"A student heats water until it boils and steam rises. Is this a chemical change?","a":"No, water is changing state, a physical change","wrong":["Yes, because bubbles formed","Yes, because heat was added","Yes, because steam is a new substance"],"why":"Steam is still water."},{"lesson":"D1","scen":true,"type":"tf","q":"A copper wire placed in a silver nitrate solution turns the solution blue and silver crystals form; this is evidence of a chemical reaction.","a":"True","why":"Color change and a new solid indicate reaction."},{"lesson":"D1","scen":true,"type":"short","q":"A factory making circuit boards produces a blue copper solution as waste. Why shouldn’t it just pour the waste down the drain?","groups":[["toxic","harm","pollut","poison","environment","water","fish","health"]],"a":"Copper solution is toxic and would pollute water and harm fish and people; it should be treated and the copper recovered.","why":"Industrial waste must be handled carefully."},{"lesson":"D1","scen":true,"type":"fill","q":"When an iron nail left outside turns reddish-brown, a new substance called ___ has formed.","alts":["rust","iron oxide"],"a":"rust","why":"Rusting is a chemical change."},{"lesson":"D1","scen":true,"type":"mc","q":"Which observation would best show a new substance formed when mixing two powders with water?","a":"A new solid with a different color settles out","wrong":["The mixture is wet","The powders get smaller as they dissolve","The cup is heavier when more water is added"],"why":"New properties = new substance."}]},{"id":"D2","title":"Atoms Rearranging and Conservation of Mass","qs":[{"lesson":"D2","scen":false,"type":"mc","q":"In a chemical reaction, atoms are","a":"rearranged","wrong":["destroyed","created","turned into energy"],"why":"Atoms are rearranged into new substances."},{"lesson":"D2","scen":false,"type":"mc","q":"In a closed system, the mass of the products compared with the reactants is","a":"equal","wrong":["greater","smaller","zero"],"why":"Mass is conserved."},{"lesson":"D2","scen":false,"type":"mc","q":"In 2 H₂ + O₂ → 2 H₂O, how many hydrogen atoms are on each side?","a":"4","wrong":["2","6","8"],"why":"2 × 2 = 4 on each side."},{"lesson":"D2","scen":false,"type":"tf","q":"A balanced equation has the same number of each type of atom on both sides.","a":"True","why":"That’s what balanced means."},{"lesson":"D2","scen":false,"type":"tf","q":"When wood burns, the atoms in it are destroyed.","a":"False","why":"The atoms go into ash, gases and smoke; none are destroyed."},{"lesson":"D2","scen":false,"type":"fill","q":"The law of conservation of ___ says matter is not created or destroyed in a reaction.","alts":["mass","matter"],"a":"mass","why":"Conservation of mass."},{"lesson":"D2","scen":false,"type":"fill","q":"A system where no matter can get in or out is a ___ system.","alts":["closed"],"a":"closed","why":"Closed systems keep mass constant."},{"lesson":"D2","scen":false,"type":"short","q":"Why does the mass of fizzing baking soda and vinegar seem to go down in an open cup?","groups":[["gas"],["escape","leave","air","out"]],"a":"A gas (carbon dioxide) is produced and escapes into the air, so it is not weighed.","why":"Open systems lose gas."},{"lesson":"D2","scen":true,"type":"mc","q":"In a sealed bag, 20 g of reactants react and the bag puffs up. What will the products’ mass be?","a":"20 g","wrong":["Less than 20 g","More than 20 g","0 g"],"why":"Sealed bag = closed system; mass conserved."},{"lesson":"D2","scen":true,"type":"mc","q":"Before a reaction an open beaker system has a mass of 150 g. After fizzing it is 146 g. What is the best explanation?","a":"4 g of gas escaped into the air","wrong":["4 g of atoms were destroyed","The scale is broken","The products are always lighter"],"why":"The missing mass left as gas."},{"lesson":"D2","scen":true,"type":"tf","q":"If steel wool burns and the ash weighs more than the steel wool, this could be because it combined with oxygen from the air.","a":"True","why":"Atoms from oxygen gas added mass."},{"lesson":"D2","scen":true,"type":"short","q":"Methane burns: CH₄ + 2 O₂ → CO₂ + 2 H₂O. Show that oxygen atoms are conserved.","groups":[["4","four"]],"a":"Left: 2 × 2 = 4 oxygen atoms. Right: 2 in CO₂ + 2 × 1 in 2 H₂O = 4. Same number on both sides.","why":"Count atoms on each side."},{"lesson":"D2","scen":true,"type":"fill","q":"5 g of substance A reacts completely with 3 g of substance B in a closed flask. The products have a mass of ___ g.","alts":["8"],"a":"8","why":"5 + 3 = 8."},{"lesson":"D2","scen":true,"type":"mc","q":"A student wants to prove mass is conserved when baking soda reacts with vinegar. Which setup is best?","a":"Do the reaction in a sealed bottle on a balance","wrong":["Use an open cup on a balance","Measure only the vinegar","Do it outside in the wind"],"why":"A closed system keeps the gas in."}]},{"id":"D3","title":"Energy in Reactions and Chemical Batteries","qs":[{"lesson":"D3","scen":false,"type":"mc","q":"An exothermic reaction","a":"releases thermal energy and warms the surroundings","wrong":["absorbs thermal energy","never changes temperature","only happens in batteries"],"why":"Exo- means out."},{"lesson":"D3","scen":false,"type":"mc","q":"An instant cold pack gets cold when squeezed. Its reaction is","a":"endothermic","wrong":["exothermic","nuclear","a physical change only"],"why":"It absorbs heat from the surroundings."},{"lesson":"D3","scen":false,"type":"mc","q":"A battery changes","a":"chemical energy into electrical energy","wrong":["electrical energy into nuclear energy","light into mass","sound into heat"],"why":"Battery reactions push electrons through a circuit."},{"lesson":"D3","scen":false,"type":"tf","q":"Burning wood is an exothermic reaction.","a":"True","why":"It releases heat and light."},{"lesson":"D3","scen":false,"type":"tf","q":"Energy is destroyed in a chemical reaction.","a":"False","why":"Energy changes form; it isn’t destroyed."},{"lesson":"D3","scen":false,"type":"fill","q":"A reaction that absorbs thermal energy is ___.","alts":["endothermic"],"a":"endothermic","why":"Endo- means in."},{"lesson":"D3","scen":false,"type":"fill","q":"A simple battery needs two different metals and an ___.","alts":["electrolyte"],"a":"electrolyte","why":"The electrolyte allows charges to move."},{"lesson":"D3","scen":false,"type":"short","q":"How could you tell whether a reaction is exothermic or endothermic?","groups":[["temperatur","thermometer","hot","warm","cold"]],"a":"Measure the temperature with a thermometer: if it rises, it’s exothermic; if it falls, it’s endothermic.","why":"Temperature change tells you."},{"lesson":"D3","scen":true,"type":"mc","q":"Mixing two chemicals raises the temperature from 22 °C to 41 °C. How much did the temperature change and what type is it?","a":"19 °C, exothermic","wrong":["19 °C, endothermic","63 °C, exothermic","41 °C, endothermic"],"why":"41 − 22 = 19; it warmed, so exothermic."},{"lesson":"D3","scen":true,"type":"mc","q":"A student builds a lemon battery with two copper strips and no zinc. The LED doesn’t light. Why?","a":"A battery needs two different metals","wrong":["Lemons can’t conduct","Copper is not a metal","The LED needs water"],"why":"Two different metals are needed."},{"lesson":"D3","scen":true,"type":"tf","q":"Adding more iron powder to a hand-warmer mixture could make it release more heat overall.","a":"True","why":"More reactant can mean more energy released."},{"lesson":"D3","scen":true,"type":"short","q":"Design idea: you need a pack that cools a sprained ankle. Which kind of reaction should it use and why?","groups":[["endotherm"],["absorb","cold","cool","take in"]],"a":"An endothermic reaction, because it absorbs thermal energy and makes the pack cold.","why":"Match reaction type to the need."},{"lesson":"D3","scen":true,"type":"fill","q":"A temperature drops from 25 °C to 10 °C during a reaction. The change is ___ °C.","alts":["15","-15","−15"],"a":"15","why":"25 − 10 = 15 degrees cooler."},{"lesson":"D3","scen":true,"type":"mc","q":"Which data table best compares four hand-warmer recipes?","a":"Starting temperature, highest temperature and time warm for each recipe","wrong":["Only the colors of the packets","The price of thermometers","The day of the week tested"],"why":"Fair comparisons need the same measurements for each."}]},{"id":"D4","title":"Engineering a Device with a Reaction","qs":[{"lesson":"D4","scen":false,"type":"mc","q":"What are criteria in engineering?","a":"Requirements a design must meet","wrong":["Limits like cost or time","The final product","A list of materials only"],"why":"Criteria define success."},{"lesson":"D4","scen":false,"type":"mc","q":"Which is a constraint?","a":"The hand warmer must cost less than $1","wrong":["The hand warmer must be warm","The hand warmer is blue","The test was fun"],"why":"Cost limits are constraints."},{"lesson":"D4","scen":false,"type":"mc","q":"What is a prototype?","a":"An early model built to test a design","wrong":["The final product sold in stores","A drawing of a scientist","A type of chemical"],"why":"Prototypes are tested and improved."},{"lesson":"D4","scen":false,"type":"tf","q":"Engineers often test and improve a design many times.","a":"True","why":"This repeating process is iteration."},{"lesson":"D4","scen":false,"type":"tf","q":"In a fair test you should change several variables at once.","a":"False","why":"Change one variable at a time so you know what caused the result."},{"lesson":"D4","scen":false,"type":"fill","q":"Repeating the cycle of testing and improving a design is called ___.","alts":["iteration","iterating","iterate"],"a":"iteration","why":"Designs improve through iteration."},{"lesson":"D4","scen":false,"type":"fill","q":"Limits on a design such as cost and safety are called ___.","alts":["constraints"],"a":"constraints","why":"Constraints restrict possible solutions."},{"lesson":"D4","scen":false,"type":"short","q":"Why should you change only one variable at a time when improving a prototype?","groups":[["cause","which change","which variable","fair","responsib","what made","affect"]],"a":"So you know which change caused the difference in the results (a fair test).","why":"Controlled variables."},{"lesson":"D4","scen":true,"type":"mc","q":"Hand warmer A reaches 45 °C for 10 min; B reaches 60 °C for 3 min. The criteria are “at least 40 °C for 8 min, never above 50 °C.” Which meets the criteria?","a":"A only","wrong":["B only","Both","Neither"],"why":"B is too hot and too short."},{"lesson":"D4","scen":true,"type":"mc","q":"A team wants to test whether more salt makes their warmer hotter. What should they keep the same?","a":"The amount of iron, water and packet size","wrong":["The amount of salt","Nothing","Only the color"],"why":"Keep all other variables constant."},{"lesson":"D4","scen":true,"type":"tf","q":"If the safest mixture is also the most expensive, the team faces a trade-off.","a":"True","why":"Improving one criterion can cost another."},{"lesson":"D4","scen":true,"type":"short","q":"Your first hand warmer cooled down too quickly. Suggest one change to test and how you’d know it worked.","groups":[["insulat","more","amount","packet","cloth","wrap","iron"],["temperatur","time","longer","measure","thermometer"]],"a":"Wrap the packet in insulating cloth (or add more iron), then measure the temperature every minute to see if it stays warm longer.","why":"Refine using data."},{"lesson":"D4","scen":true,"type":"fill","q":"A warmer must stay above 40 °C for 8 minutes. Staying warm for 8 minutes is one of the design ___.","alts":["criteria","criterion"],"a":"criteria","why":"It’s a requirement."},{"lesson":"D4","scen":true,"type":"mc","q":"Which result best shows the refined design improved?","a":"Temperature data showing it stayed warm 4 minutes longer than before","wrong":["It looked nicer","The team liked it more","It used a different color packet"],"why":"Data against the criteria shows improvement."}]},{"id":"D5","title":"Recovering Copper","qs":[{"lesson":"D5","scen":false,"type":"mc","q":"Why do factories try to recover copper from waste solutions?","a":"Copper is harmful in water and valuable to reuse","wrong":["Copper makes water taste better","It is required to make the waste blue","Copper turns into gold"],"why":"Recovery protects the environment and saves resources."},{"lesson":"D5","scen":false,"type":"mc","q":"Placing an iron nail in blue copper solution causes","a":"reddish copper to coat the nail","wrong":["the nail to turn to gold","nothing to happen","the solution to get bluer"],"why":"Iron is more reactive and displaces copper."},{"lesson":"D5","scen":false,"type":"mc","q":"A blue solution fading as copper is recovered shows","a":"less copper remains dissolved","wrong":["more copper dissolved","the water evaporated","the reaction stopped immediately"],"why":"The blue color comes from dissolved copper."},{"lesson":"D5","scen":false,"type":"tf","q":"Recovering copper from waste can reduce the need to mine new copper ore.","a":"True","why":"Recovered copper is reused."},{"lesson":"D5","scen":false,"type":"tf","q":"All recovery methods produce no waste at all.","a":"False","why":"Most methods create some new waste, a trade-off to consider."},{"lesson":"D5","scen":false,"type":"fill","q":"Getting a useful material back out of waste is called ___ it.","alts":["recovering","recovery","recover"],"a":"recovering","why":"Recovery saves resources."},{"lesson":"D5","scen":false,"type":"fill","q":"Zinc can remove copper from solution because zinc is more ___ than copper.","alts":["reactive"],"a":"reactive","why":"More reactive metals displace less reactive ones."},{"lesson":"D5","scen":false,"type":"short","q":"Give two things you would compare when choosing between two copper-recovery methods.","groups":[["amount","how much","mass","yield","cost","price","time","waste","safe"],["amount","how much","mass","yield","cost","price","time","waste","safe"]],"a":"How much copper each recovers and the cost (also time and leftover waste).","why":"Compare methods with several criteria."},{"lesson":"D5","scen":true,"type":"mc","q":"Method 1 recovers 1.8 g of copper; Method 2 recovers 1.2 g from the same solution. What percent more does Method 1 recover than Method 2?","a":"50%","wrong":["60%","33%","18%"],"why":"(1.8 − 1.2) ÷ 1.2 = 0.5 = 50%."},{"lesson":"D5","scen":true,"type":"mc","q":"After adding steel wool, a copper solution goes from dark blue to almost clear. What does this tell you?","a":"Most of the copper has been removed from the solution","wrong":["The solution has more copper","The steel wool dissolved completely with no effect","Copper is not in the solution anymore because it evaporated"],"why":"Fading blue means less dissolved copper."},{"lesson":"D5","scen":true,"type":"tf","q":"A method that recovers the most copper but creates a new toxic waste might not be the best choice.","a":"True","why":"Trade-offs include new waste."},{"lesson":"D5","scen":true,"type":"short","q":"A school lab collects blue copper waste. Propose a way to treat it before disposal and explain.","groups":[["iron","zinc","nail","steel","metal"],["copper","solid","recover"]],"a":"Add iron or zinc so solid copper comes out of solution; filter out the copper to reuse, leaving less hazardous liquid.","why":"Displacement recovers copper."},{"lesson":"D5","scen":true,"type":"fill","q":"Starting with 2.0 g of dissolved copper, a method recovers 1.5 g. It recovered ___ % of the copper.","alts":["75"],"a":"75","why":"1.5 ÷ 2.0 = 0.75 = 75%."},{"lesson":"D5","scen":true,"type":"mc","q":"Which evidence shows copper was recovered by a nail?","a":"A reddish-brown coating forms on the nail","wrong":["The nail gets cold","Bubbles never form","The nail floats"],"why":"Copper metal is reddish-brown."}]}]},"5":{"num":5,"letter":"E","title":"Biomedical Engineering","lessons":[{"id":"E1","title":"What Engineers Do","qs":[{"lesson":"E1","scen":false,"type":"mc","q":"Biomedical engineers mainly design","a":"devices and solutions for the human body and health","wrong":["bridges and roads only","new chemical elements","weather forecasts"],"why":"Bio = life, medical = health."},{"lesson":"E1","scen":false,"type":"mc","q":"What is usually the FIRST step in the engineering design process?","a":"Define the problem","wrong":["Build the final product","Sell the design","Paint the prototype"],"why":"You must understand the problem first."},{"lesson":"E1","scen":false,"type":"mc","q":"Which is a difference between scientists and engineers?","a":"Scientists ask questions about the natural world; engineers design solutions to problems","wrong":["Engineers never use science","Scientists never do experiments","There is no difference"],"why":"Science explains; engineering solves."},{"lesson":"E1","scen":false,"type":"tf","q":"Engineers often brainstorm many ideas before choosing one.","a":"True","why":"More ideas lead to better choices."},{"lesson":"E1","scen":false,"type":"tf","q":"A good engineer builds only one design and never changes it.","a":"False","why":"Engineers test and improve designs."},{"lesson":"E1","scen":false,"type":"fill","q":"Limits such as cost, time and materials are called ___.","alts":["constraints"],"a":"constraints","why":"Constraints narrow the options."},{"lesson":"E1","scen":false,"type":"fill","q":"Engineers who design artificial limbs and heart valves work in ___ engineering.","alts":["biomedical","bio-medical"],"a":"biomedical","why":"Biomedical engineering."},{"lesson":"E1","scen":false,"type":"short","q":"Why is it important to talk to the people who will use a medical device when designing it?","groups":[["need","use","comfort","fit","work","problem","feedback"]],"a":"So the design meets their real needs (comfort, fit, ease of use); their feedback shows what criteria matter.","why":"Users define criteria."},{"lesson":"E1","scen":true,"type":"mc","q":"In the “Save Fred” challenge, a team must move a gummy figure using only paper clips without touching it. What should they do first?","a":"Discuss the rules and plan a strategy","wrong":["Grab the gummy with their hands","Use scissors not allowed in the rules","Give up"],"why":"Defining the problem and constraints comes first."},{"lesson":"E1","scen":true,"type":"mc","q":"A team’s first prototype fails a test. The best next step is to","a":"use the test data to improve the design and retest","wrong":["throw out all their ideas","claim it passed","change every part at once without testing"],"why":"Iteration uses data."},{"lesson":"E1","scen":true,"type":"tf","q":"A wheelchair ramp design that meets the criteria but costs far more than the budget allows does not meet all the constraints.","a":"True","why":"Budget is a constraint."},{"lesson":"E1","scen":true,"type":"short","q":"You’re designing a pill reminder for a grandparent. List one criterion and one constraint.","groups":[["remind","alert","easy","simple","loud","time","must"],["cost","budget","$","size","small","battery","limit"]],"a":"Criterion: it must alert at the right time and be easy to read. Constraint: it must cost under $20.","why":"Criteria vs constraints."},{"lesson":"E1","scen":true,"type":"fill","q":"Building and testing an early model of a design means making a ___.","alts":["prototype"],"a":"prototype","why":"Prototypes are tested."},{"lesson":"E1","scen":true,"type":"mc","q":"Two designs both meet the criteria. How should engineers choose?","a":"Compare trade-offs like cost, safety and reliability using data","wrong":["Pick the one they drew first","Flip a coin without data","Choose the heavier one"],"why":"Use evidence to decide."}]},{"id":"E2","title":"Body Systems and Bionic Replacements","qs":[{"lesson":"E2","scen":false,"type":"mc","q":"Which shows the correct order from smallest to largest?","a":"cell, tissue, organ, organ system","wrong":["organ, cell, tissue, organ system","tissue, cell, organ system, organ","organ system, organ, tissue, cell"],"why":"Cells build tissues, which build organs."},{"lesson":"E2","scen":false,"type":"mc","q":"The heart is part of which system?","a":"Circulatory","wrong":["Skeletal","Digestive","Respiratory"],"why":"It pumps blood through vessels."},{"lesson":"E2","scen":false,"type":"mc","q":"A prosthesis is","a":"an artificial replacement for a body part","wrong":["a type of cell","a bone disease","a kind of medicine"],"why":"Prosthetic legs and hands are examples."},{"lesson":"E2","scen":false,"type":"tf","q":"Body systems work independently and never affect each other.","a":"False","why":"Systems interact; muscles and bones work together, for example."},{"lesson":"E2","scen":false,"type":"tf","q":"Materials used inside the body must be biocompatible.","a":"True","why":"They must not cause harmful reactions."},{"lesson":"E2","scen":false,"type":"fill","q":"A group of similar cells working together is a ___.","alts":["tissue"],"a":"tissue","why":"Tissues form organs."},{"lesson":"E2","scen":false,"type":"fill","q":"The ___ system includes bones that support and protect the body.","alts":["skeletal"],"a":"skeletal","why":"Skeletal system."},{"lesson":"E2","scen":false,"type":"short","q":"Explain how the muscular and skeletal systems work together.","groups":[["muscle"],["bone"],["move","pull","contract"]],"a":"Muscles attach to bones and pull on them when they contract, which moves the bones at joints.","why":"Systems interact."},{"lesson":"E2","scen":true,"type":"mc","q":"A person’s heart beats too slowly. Which device would a biomedical engineer most likely design?","a":"A pacemaker","wrong":["A hearing aid","A knee replacement","Contact lenses"],"why":"Pacemakers regulate heartbeat."},{"lesson":"E2","scen":true,"type":"mc","q":"Engineers choose titanium for a hip implant. Which property is MOST important for this choice?","a":"It is strong and biocompatible","wrong":["It is shiny","It is cheap glass","It dissolves quickly"],"why":"Implants must be strong and safe in the body."},{"lesson":"E2","scen":true,"type":"tf","q":"If damaged lungs take in less oxygen, the muscles may tire faster because the circulatory system delivers less oxygen.","a":"True","why":"Respiratory and circulatory systems are linked."},{"lesson":"E2","scen":true,"type":"short","q":"A runner loses part of a leg. Name two criteria for a good prosthetic leg.","groups":[["light","weight"],["strong","durab","comfort","fit","flex","spring","bend","safe"]],"a":"It must be strong enough to hold the runner’s weight and light and comfortable enough to run in.","why":"Criteria match function."},{"lesson":"E2","scen":true,"type":"fill","q":"An artificial part that replaces a missing leg is called a ___.","alts":["prosthesis","prosthetic","prosthetic leg"],"a":"prosthesis","why":"Prosthesis."},{"lesson":"E2","scen":true,"type":"mc","q":"Why might an implant material that causes swelling be rejected?","a":"It is not biocompatible","wrong":["It is too strong","It is too light","It costs too little"],"why":"Harmful reactions mean it’s not biocompatible."}]},{"id":"E3","title":"Artificial Bone and Heart Valve Models","qs":[{"lesson":"E3","scen":false,"type":"mc","q":"What does a heart valve do?","a":"Lets blood flow in one direction","wrong":["Makes red blood cells","Digests food","Moves the bones"],"why":"Valves stop backflow."},{"lesson":"E3","scen":false,"type":"mc","q":"Why is the inside of many bones spongy rather than solid?","a":"It keeps bones strong but lighter","wrong":["Bones are rotting","It makes bones heavier","It stores air for breathing"],"why":"Spongy structure saves weight."},{"lesson":"E3","scen":false,"type":"mc","q":"The force a structure must hold up is called the","a":"load","wrong":["valve","criteria","tissue"],"why":"Load = force on a structure."},{"lesson":"E3","scen":false,"type":"tf","q":"A model artificial bone can be tested before anything is used in a real patient.","a":"True","why":"Models make testing safe."},{"lesson":"E3","scen":false,"type":"tf","q":"A good artificial heart valve should leak backward a little each beat.","a":"False","why":"It must seal to stop backflow."},{"lesson":"E3","scen":false,"type":"fill","q":"Blood flowing the wrong direction through the heart is called ___.","alts":["backflow","back flow"],"a":"backflow","why":"Valves prevent backflow."},{"lesson":"E3","scen":false,"type":"fill","q":"A valve lets fluid flow in only ___ direction.","alts":["one","1"],"a":"one","why":"One-way."},{"lesson":"E3","scen":false,"type":"short","q":"Give one limitation of using a paper-and-tape model of a bone.","groups":[["not real","different","material","living","grow","heal","real bone"]],"a":"Paper doesn’t behave like living bone: it can’t grow or heal and bends differently, so results may not match real bones.","why":"Models have limits."},{"lesson":"E3","scen":true,"type":"mc","q":"Model bone A (hollow tube) holds 4 kg; model B (solid, twice the mass) holds 4.5 kg. If lightness matters too, which is the better design?","a":"A, because it is nearly as strong and much lighter","wrong":["B, because it held more","Neither is useful","Both are exactly equal"],"why":"Trade-off between strength and mass."},{"lesson":"E3","scen":true,"type":"mc","q":"To compare three bone designs fairly, the team should","a":"use the same length, materials budget and loading method for each","wrong":["test each with different weights","test one design only","let each member test differently"],"why":"Control variables."},{"lesson":"E3","scen":true,"type":"tf","q":"An artificial heart valve must work reliably for millions of beats, so durability is a key criterion.","a":"True","why":"The heart beats about 100,000 times a day."},{"lesson":"E3","scen":true,"type":"short","q":"A valve model lets water through in both directions. How would you redesign it?","groups":[["flap","seal","close","one way","one-way","hinge","stop"]],"a":"Add a flap that swings open only one way and seals against a rim when water pushes back, stopping backflow.","why":"Function: one-way flow."},{"lesson":"E3","scen":true,"type":"fill","q":"A heart beats about 70 times per minute. In one hour it beats about ___ times.","alts":["4200"],"a":"4200","why":"70 × 60 = 4,200."},{"lesson":"E3","scen":true,"type":"mc","q":"Which test result shows an artificial valve works well?","a":"Water flows forward easily and almost none flows back","wrong":["Water flows both ways equally","No water flows at all","The valve breaks after one use"],"why":"One-way, low resistance, durable."}]},{"id":"E4","title":"Criteria, Constraints and Trade-offs","qs":[{"lesson":"E4","scen":false,"type":"mc","q":"What is a trade-off?","a":"Giving up some of one quality to gain another","wrong":["A design that has no flaws","A type of constraint that is always cost","Swapping teams"],"why":"Trade-offs balance competing needs."},{"lesson":"E4","scen":false,"type":"mc","q":"A decision matrix helps engineers","a":"compare options against criteria","wrong":["build prototypes faster","avoid testing","choose colors"],"why":"It scores options fairly."},{"lesson":"E4","scen":false,"type":"mc","q":"For a snack bar for students with nut allergies, “contains no nuts” is a","a":"constraint (a firm requirement/limit)","wrong":["trade-off","decision matrix","prototype"],"why":"It limits the possible ingredients."},{"lesson":"E4","scen":false,"type":"tf","q":"Weighting a criterion means it counts more in the total score.","a":"True","why":"Important criteria get extra weight."},{"lesson":"E4","scen":false,"type":"tf","q":"A perfect design never involves trade-offs.","a":"False","why":"Almost all designs involve trade-offs."},{"lesson":"E4","scen":false,"type":"fill","q":"Making a design as good as possible within the constraints is called ___ it.","alts":["optimizing","optimising","optimize"],"a":"optimizing","why":"Optimize = best within limits."},{"lesson":"E4","scen":false,"type":"fill","q":"A table that scores each design option on each criterion is a decision ___.","alts":["matrix"],"a":"matrix","why":"Decision matrix."},{"lesson":"E4","scen":false,"type":"short","q":"Explain a trade-off in designing a snack bar.","groups":[["tast","sugar","sweet","cost","cheap","protein","health","nutri"],["but","less","more","worse"]],"a":"Adding more protein makes it healthier but may cost more or taste worse, so you give up some of one to gain the other.","why":"Trade-offs are about gains and losses."},{"lesson":"E4","scen":true,"type":"mc","q":"Bar A scores cost 5, protein 2, taste 4. Bar B scores cost 3, protein 5, taste 3. If protein is weighted ×2, which wins?","a":"B (3 + 10 + 3 = 16 vs A 5 + 4 + 4 = 13)","wrong":["A (5 + 2 + 4 = 11)","They tie","Cannot tell"],"why":"Double the protein scores, then add."},{"lesson":"E4","scen":true,"type":"mc","q":"A snack bar for hikers must be light and high-energy. Which is the best criterion to test?","a":"Calories per gram","wrong":["The color of the wrapper","The brand name","How it smells when burned"],"why":"Energy per weight matches the need."},{"lesson":"E4","scen":true,"type":"tf","q":"If a cheaper material makes a prosthetic hand heavier, choosing it involves a trade-off.","a":"True","why":"Cost vs weight."},{"lesson":"E4","scen":true,"type":"short","q":"Your team’s two snack bar designs tie in the decision matrix. What could you do next?","groups":[["test","survey","taste","data","weight","user","criteria"]],"a":"Run another test (for example, a taste survey with the target users) or weight the most important criterion to break the tie.","why":"Use more evidence."},{"lesson":"E4","scen":true,"type":"fill","q":"Design X scores 4, 3 and 5 on three criteria. Its total score is ___.","alts":["12"],"a":"12","why":"4 + 3 + 5 = 12."},{"lesson":"E4","scen":true,"type":"mc","q":"Which reason best justifies choosing a design?","a":"It scored highest on the most important criteria in testing","wrong":["It was the first idea","The leader liked its name","It was the most expensive"],"why":"Justify with evidence."}]},{"id":"E5","title":"Biomechanics and Grip","qs":[{"lesson":"E5","scen":false,"type":"mc","q":"Muscles move bones by","a":"pulling on them","wrong":["pushing on them","dissolving them","making them longer"],"why":"Muscles can only pull."},{"lesson":"E5","scen":false,"type":"mc","q":"What connects a muscle to a bone?","a":"A tendon","wrong":["A ligament","A nerve","A valve"],"why":"Tendons attach muscles to bones."},{"lesson":"E5","scen":false,"type":"mc","q":"When the biceps contracts, the elbow","a":"bends","wrong":["straightens","locks forever","disappears"],"why":"The biceps pulls the forearm up."},{"lesson":"E5","scen":false,"type":"tf","q":"Muscles work in pairs because each muscle can only pull, not push.","a":"True","why":"Opposing pairs move a joint both ways."},{"lesson":"E5","scen":false,"type":"tf","q":"Friction makes it harder to grip an object.","a":"False","why":"Friction helps prevent slipping, making grip easier."},{"lesson":"E5","scen":false,"type":"fill","q":"A place where two bones meet and move is a ___.","alts":["joint"],"a":"joint","why":"Joints act as pivots."},{"lesson":"E5","scen":false,"type":"fill","q":"A thumb that can touch each fingertip is called an ___ thumb.","alts":["opposable"],"a":"opposable","why":"It allows precise and strong grips."},{"lesson":"E5","scen":false,"type":"short","q":"Why do robot and prosthetic hands often have rubber fingertips?","groups":[["friction","grip","slip","hold"]],"a":"Rubber increases friction so objects don’t slip out of the hand.","why":"Friction aids grip."},{"lesson":"E5","scen":true,"type":"mc","q":"A cardboard hand model uses strings for tendons. Pulling a string bends a finger. To straighten it again, the design needs","a":"a second string or spring pulling the other way","wrong":["a longer first string","more cardboard","no changes"],"why":"Like muscle pairs, movement both ways needs opposing pulls."},{"lesson":"E5","scen":true,"type":"mc","q":"A prosthetic hand can lift a cup but drops a smooth glass. What should engineers change first?","a":"Add higher-friction material to the gripping surfaces","wrong":["Make the hand a different color","Remove the thumb","Make the fingers rigid and unmoving"],"why":"Smooth objects need more friction."},{"lesson":"E5","scen":true,"type":"tf","q":"Taping your thumb to your hand would make it harder to pick up a pencil because the thumb can no longer oppose the fingers.","a":"True","why":"Opposable thumbs enable precise grips."},{"lesson":"E5","scen":true,"type":"short","q":"You’re designing a gripper for a person who can’t close their hand. Name one feature you’d copy from the human hand and why.","groups":[["thumb","joint","tendon","string","friction","rubber","finger","bend"],["grip","hold","pick"]],"a":"An opposable thumb so the gripper can pinch and hold objects (or bendable joints with tendon-like strings to curl the fingers).","why":"Biomimicry of hand structures."},{"lesson":"E5","scen":true,"type":"fill","q":"When you straighten your arm, the ___ muscle contracts.","alts":["triceps","tricep"],"a":"triceps","why":"Triceps straightens the elbow."},{"lesson":"E5","scen":true,"type":"mc","q":"Which test gives the best data on a grip design?","a":"Measure the heaviest mass of several objects it can hold without slipping","wrong":["Ask if it looks cool","Test it once on a feather","Measure the length of the box"],"why":"Quantitative, repeatable tests."}]}]}};
